import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"Migrating from Codeberg - v6","description":"How to move your Textwire project from codeberg.org/textwire/textwire/v5 to github.com/textwire/textwire/v6","frontmatter":{"title":"Migrating from Codeberg - v6","description":"How to move your Textwire project from codeberg.org/textwire/textwire/v5 to github.com/textwire/textwire/v6","outline":"deep"},"headers":[],"relativePath":"codeberg-migration.md","filePath":"src/codeberg-migration.md","lastUpdated":1795359991000}`),a={name:`codeberg-migration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrating-from-codeberg" tabindex="-1">Migrating from Codeberg <a class="header-anchor" href="#migrating-from-codeberg" aria-label="Permalink to “Migrating from Codeberg”">​</a></h1><p>Textwire started on GitHub, moved to Codeberg in the middle of v5, and v6 is back on GitHub. So the module path changed from <code>codeberg.org/textwire/textwire/v5</code> to <code>github.com/textwire/textwire/v6</code>.</p><p>This only affects you if you installed Textwire from Codeberg. If you stayed on GitHub, your import already points to the right place and only the <code>v5</code> suffix needs to become <code>v6</code>.</p><p>Update your imports first, then go through the <a href="/upgrade">Upgrade Guide</a> for the breaking changes between v5 and v6.</p><h2 id="_1-update-import-paths" tabindex="-1">1. Update Import Paths <a class="header-anchor" href="#_1-update-import-paths" aria-label="Permalink to “1. Update Import Paths”">​</a></h2><p>Replace the module path in every <code>.go</code> file. Because the whole prefix is replaced, subpackages like <code>.../pkg/evaluator</code> are updated too:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> -rl</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;codeberg.org/textwire/textwire/v5&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;">&#39;*.go&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#F5C2E7;"> \\</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#94E2D5;">    |</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> xargs</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;s|codeberg.org/textwire/textwire/v5|github.com/textwire/textwire/v6|g&#39;</span></span></code></pre></div><p>On macOS, BSD <code>sed</code> needs an empty argument after <code>-i</code>:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> -rl</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;codeberg.org/textwire/textwire/v5&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;">&#39;*.go&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#F5C2E7;"> \\</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#94E2D5;">    |</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> xargs</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;s|codeberg.org/textwire/textwire/v5|github.com/textwire/textwire/v6|g&#39;</span></span></code></pre></div><h2 id="_2-update-dependencies" tabindex="-1">2. Update Dependencies <a class="header-anchor" href="#_2-update-dependencies" aria-label="Permalink to “2. Update Dependencies”">​</a></h2><p>Run <code>go mod tidy</code> to fetch v6 and remove the old requirement. Version 6 requires Go <code>1.25</code> or higher.</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> tidy</span></span></code></pre></div><p>Verify that no old imports are left:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &#39;codeberg.org/textwire&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#A6E3A1;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;">&#39;*.go&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> .</span></span></code></pre></div><p>The command should print nothing.</p><h2 id="_3-follow-the-upgrade-guide" tabindex="-1">3. Follow the Upgrade Guide <a class="header-anchor" href="#_3-follow-the-upgrade-guide" aria-label="Permalink to “3. Follow the Upgrade Guide”">​</a></h2><p>Once your imports point to v6 and the project compiles, complete the <a href="/upgrade">Upgrade Guide</a>. It covers the breaking changes between v5 and v6, such as the <code>loop</code> object in nested loops, whitespace handling, <code>defined()</code> checks, escaped <code>@insert</code> and <code>@reserve</code> values, read-only global data, and the <code>pkg/</code> API changes.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};